# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs, offset=-1):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: fold
def fold(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(digest(sift(emit(shape(raw)))))

